--
-- Estructura para la vista `v_equipos_resumen`
--
DROP TABLE IF EXISTS `v_equipos_resumen`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_equipos_resumen`  AS SELECT `e`.`id` AS `id`, `e`.`item` AS `item`, `e`.`sede` AS `sede`, `e`.`area` AS `area`, `e`.`responsable` AS `responsable`, `e`.`componente` AS `componente`, `e`.`tipo_equipo` AS `tipo_equipo`, `e`.`marca` AS `marca`, `e`.`modelo` AS `modelo`, `e`.`serial` AS `serial`, `e`.`sistema_op` AS `sistema_op`, `e`.`ip_local` AS `ip_local`, `e`.`office` AS `office`, `e`.`fecha_registro` AS `fecha_registro`, count(`s`.`id`) AS `total_software` FROM (`equipos` `e` left join `software` `s` on(`s`.`equipo_id` = `e`.`id`)) GROUP BY `e`.`id` ;

